135	#[test]
136	fn filename_with_spaces_and_non_ascii_characters_is_read() {
137	    let dir = TestDir::new("unicode-names");
138	    // 空格、中文、其他非 ASCII 字符都应与普通路径一样成功读取。
139	    for name in ["my file.txt", "报告 最终版.txt", "données été.bin"] {
140	        let path = dir.write_file(OsStr::new(name), b"abc");
141	        let output = run_digest(path.as_os_str());
142	        let hex = assert_success(&output);
143	        assert_eq!(hex, ABC_HEX, "digest for file named {name:?}");
144	    }
145	}
