194	#[test]
195	fn missing_file_reports_error_with_path() {
196	    let dir = TestDir::new("missing");
197	    let path = dir.path().join("nope.txt");
198	
199	    let output = run_digest(path.as_os_str());
200	
201	    let stderr = assert_failure(&output);
202	    assert!(
203	        stderr.contains("cannot open"),
204	        "should report open failure: {stderr:?}"
205	    );
206	    assert!(
207	        stderr.contains("nope.txt"),
208	        "error must name the failing path: {stderr:?}"
209	    );
210	    // 用户必须能区分成功摘要和失败提示：失败时标准输出没有任何摘要。
211	    assert!(output.stdout.is_empty());
212	}
