229	#[test]
230	fn control_characters_in_error_path_are_escaped_visibly() {
231	    let dir = TestDir::new("control-chars");
232	    // 不存在的路径，名字含换行、制表符和响铃符。
233	    let path = dir.path().join("bad\nname\ttab\u{7}bell.txt");
234	
235	    let output = run_digest(path.as_os_str());
236	
237	    let stderr = assert_failure(&output);
238	    // 控制字符必须以可见转义形式出现，不得改变提示的行结构。
239	    assert!(stderr.contains("bad\\nname\\ttab\\u{7}bell.txt"), "{stderr:?}");
240	    assert!(!stderr.contains("bad\nname"), "{stderr:?}");
241	    assert!(!stderr.contains('\t'), "{stderr:?}");
242	}
