244	#[cfg(unix)]
245	mod unix {
246	    use super::*;
247	    use std::os::unix::ffi::OsStrExt;
248	
249	    fn os(bytes: &[u8]) -> OsString {
250	        OsString::from(OsStr::from_bytes(bytes))
251	    }
252	
253	    #[test]
254	    fn non_utf8_filename_is_read_like_any_other_path() {
255	        let dir = TestDir::new("non-utf8");
256	        let path = dir.write_file(&os(b"raw \xff\xfe name.bin"), b"abc");
257	
258	        let output = run_digest(path.as_os_str());
259	
260	        let hex = assert_success(&output);
261	        assert_eq!(hex, ABC_HEX);
262	    }
