264	    #[test]
265	    fn paths_differing_only_in_undecodable_bytes_reach_their_own_files() {
266	        let dir = TestDir::new("undecodable-pair");
267	        // 两个真实路径只在不可解码字节上不同，损失性显示文字相同。
268	        let first = dir.write_file(&os(b"data_\xff.bin"), b"content of first");
269	        let second = dir.write_file(&os(b"data_\xfe.bin"), b"content of second");
270	
271	        // 测试前提：两个路径的显示文字确实相同（都含替换字符）。
272	        let display_first = first.as_os_str().to_string_lossy().into_owned();
273	        let display_second = second.as_os_str().to_string_lossy().into_owned();
274	        assert_eq!(display_first, display_second);
275	        assert!(display_first.contains('\u{fffd}'));
276	
277	        // 各自得到对应内容的摘要，不能读到另一个文件。
278	        let hex_first = assert_success(&run_digest(first.as_os_str()));
279	        let hex_second = assert_success(&run_digest(second.as_os_str()));
280	        assert_eq!(
281	            hex_first,
282	            inkseal::digest_reader(&b"content of first"[..])
283	                .unwrap()
284	                .to_hex()
285	        );
286	        assert_eq!(
287	            hex_second,
288	            inkseal::digest_reader(&b"content of second"[..])
289	                .unwrap()
290	                .to_hex()
291	        );
292	        assert_ne!(hex_first, hex_second);
293	    }
294	
295	    #[test]
296	    fn missing_undecodable_path_reports_not_found_without_reading_sibling() {
297	        let dir = TestDir::new("undecodable-missing");
298	        // 只创建 \xff 版本；访问 \xfe 版本必须报文件不存在，
299	        // 不能因显示文字相同而误读已有文件。
300	        let existing = dir.write_file(&os(b"data_\xff.bin"), b"existing content");
301	        let missing = dir.path().join(os(b"data_\xfe.bin"));
302	
303	        let output = run_digest(missing.as_os_str());
304	
305	        let stderr = assert_failure(&output);
306	        // 提示中的替换字符只影响显示：两个路径显示文字相同，但行为不同。
307	        assert!(stderr.contains('\u{fffd}'), "{stderr:?}");
308	        assert!(stderr.contains("cannot open"), "{stderr:?}");
309	        // 绝不能输出已有文件的摘要。
310	        let existing_hex = inkseal::digest_reader(&b"existing content"[..])
311	            .unwrap()
312	            .to_hex();
313	        assert!(!output.stdout.windows(64).any(|w| w == existing_hex.as_bytes()));
314	        // 对照：已有文件本身可以正常摘要。
315	        let hex = assert_success(&run_digest(existing.as_os_str()));
316	        assert_eq!(hex, existing_hex);
317	    }
