319	    #[test]
320	    fn undecodable_bytes_in_error_path_shown_as_replacement_char() {
321	        let dir = TestDir::new("undecodable-error");
322	        // 不存在的路径，同时含不可解码字节和控制字符。
323	        let path = dir.path().join(os(b"bad\xff\nname"));
324	
325	        let output = run_digest(path.as_os_str());
326	
327	        let stderr = assert_failure(&output);
328	        // 不可解码字节以替换字符呈现，换行以可见转义呈现，提示仍是单行。
329	        assert!(stderr.contains('\u{fffd}'), "{stderr:?}");
330	        assert!(stderr.contains("\\n"), "{stderr:?}");
331	        assert!(!stderr[..stderr.len() - 1].contains('\n'), "{stderr:?}");
332	    }
333	}
