374	// ── check-digest ────────────────────────────────────────────────────────────
375	
376	fn run_check(path: &OsStr, expected: &OsStr) -> Output {
377	    inkseal()
378	        .arg("check-digest")
379	        .arg(path)
380	        .arg(expected)
381	        .output()
382	        .expect("failed to run inkseal")
383	}
