385	/// 匹配的完整约定：退出码 0、标准输出只有 `OK\n`、标准错误为空。
386	fn assert_check_ok(output: &Output) {
387	    assert_eq!(output.status.code(), Some(0), "exit code: {output:?}");
388	    assert_eq!(output.stdout, b"OK\n", "stdout must be exactly OK\\n: {output:?}");
389	    assert!(
390	        output.stderr.is_empty(),
391	        "stderr must be empty on match: {:?}",
392	        String::from_utf8_lossy(&output.stderr)
393	    );
394	}
395	
396	/// 内容不匹配的完整约定：退出码 1、标准输出为空、标准错误说明不匹配
397	/// 并列出预期与实际两个 64 位小写十六进制摘要。
398	fn assert_mismatch(output: &Output, expected_hex: &str, actual_hex: &str) -> String {
399	    assert_eq!(output.status.code(), Some(1), "exit code: {output:?}");
400	    assert!(
401	        output.stdout.is_empty(),
402	        "stdout must be empty on mismatch: {:?}",
403	        String::from_utf8_lossy(&output.stdout)
404	    );
405	    let stderr = String::from_utf8(output.stderr.clone()).expect("stderr must be UTF-8");
406	    assert!(
407	        stderr.to_lowercase().contains("mismatch"),
408	        "must state content mismatch, not an I/O error: {stderr:?}"
409	    );
410	    assert!(
411	        stderr.contains(expected_hex),
412	        "must list expected digest: {stderr:?}"
413	    );
414	    assert!(
415	        stderr.contains(actual_hex),
416	        "must list actual digest: {stderr:?}"
417	    );
418	    // 两者都必须以 64 个小写十六进制字符出现。
419	    for line in stderr.lines() {
420	        if let Some(hex) = line.split_whitespace().find(|w| w.len() == 64) {
421	            assert!(
422	                hex.chars().all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()),
423	                "digest in message must be lowercase hex: {hex:?}"
424	            );
425	        }
426	    }
427	    stderr
428	}
