444	fn check_digest_matches_when_content_unchanged() {
445	    let dir = TestDir::new("check-ok");
446	    let path = dir.write_file(OsStr::new("hello.txt"), b"abc");
447	
448	    let output = run_check(path.as_os_str(), OsStr::new(ABC_HEX));
449	
450	    assert_check_ok(&output);
