453	#[test]
454	fn check_digest_accepts_uppercase_and_mixed_case_hex() {
455	    let dir = TestDir::new("check-case");
456	    let path = dir.write_file(OsStr::new("hello.txt"), b"abc");
457	
458	    let upper: String = ABC_HEX.to_uppercase();
459	    let mixed: String = ABC_HEX
460	        .chars()
461	        .enumerate()
462	        .map(|(i, c)| if i % 2 == 0 { c.to_ascii_uppercase() } else { c })
463	        .collect();
464	
465	    assert_check_ok(&run_check(path.as_os_str(), OsStr::new(&upper)));
466	    assert_check_ok(&run_check(path.as_os_str(), OsStr::new(&mixed)));
467	}
