469	#[test]
470	fn check_digest_mismatch_lists_both_digests_lowercase() {
471	    let dir = TestDir::new("check-mismatch");
472	    let path = dir.write_file(OsStr::new("hello.txt"), b"abc");
473	
474	    // 文件是 "abc"，却给出空文件的摘要作为预期值。
475	    let empty_hex = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
476	    let output = run_check(path.as_os_str(), OsStr::new(empty_hex));
477	
478	    let stderr = assert_mismatch(&output, empty_hex, ABC_HEX);
479	    // 预期值在提示中保持小写呈现，即使输入本身是大写。
480	    let output_upper = run_check(path.as_os_str(), OsStr::new(&empty_hex.to_uppercase()));
481	    let stderr_upper = assert_mismatch(&output_upper, empty_hex, ABC_HEX);
482	    assert!(stderr_upper.contains(empty_hex));
483	    assert!(!stderr_upper.contains(&empty_hex.to_uppercase()));
484	    // 不能伪装成文件访问问题。
485	    assert!(!stderr.contains("cannot open"));
486	    assert!(!stderr.contains("cannot read"));
487	}
