489	#[test]
490	fn check_digest_works_for_empty_and_binary_files() {
491	    let dir = TestDir::new("check-empty-binary");
492	
493	    let empty = dir.write_file(OsStr::new("empty"), b"");
494	    let empty_hex = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
495	    assert_check_ok(&run_check(empty.as_os_str(), OsStr::new(empty_hex)));
