1	//! inkseal 的库接口：对任意实现 [`std::io::Read`] 的输入计算 SHA-256 摘要，
2	//! 以及导入 DER 编码（SubjectPublicKeyInfo）的 Ed25519 公钥。
3	//!
4	//! 摘要只取决于输入的原始字节，与命令行 `inkseal digest <文件>` 遵循同一内容规则。
5	//! 公钥导入只确认编码被接受，不表示已验证任何签名或确认公钥持有者的身份。
6	
7	use sha2::{Digest, Sha256};
8	use std::error::Error;
9	use std::fmt;
10	use std::io::{self, Read};
11	
12	/// SHA-256 摘要结果，可表示为 64 个小写十六进制字符。
13	#[derive(Clone, Copy, PartialEq, Eq, Hash)]
14	pub struct Sha256Digest([u8; 32]);
15	
16	impl Sha256Digest {
17	    /// 返回摘要的原始 32 字节。
18	    pub fn as_bytes(&self) -> &[u8; 32] {
19	        &self.0
20	    }
21	
22	    /// 返回 64 个小写十六进制字符，与命令行输出一致（不含换行）。
23	    pub fn to_hex(&self) -> String {
24	        let mut hex = String::with_capacity(64);
25	        for byte in self.0 {
26	            hex.push(char::from_digit((byte >> 4) as u32, 16).unwrap());
27	            hex.push(char::from_digit((byte & 0x0f) as u32, 16).unwrap());
28	        }
29	        hex
30	    }
31	
32	    /// 从十六进制文本的原始字节解析摘要。
33	    ///
34	    /// 这是摘要文字还原的唯一规则：[`FromStr`] 只是在 `&str` 上委托给本
35	    /// 方法，命令行核对摘要时也直接使用它，因此从文本解析、按值比较与再次
36	    /// 显示永远遵循同一套规则。接受 `0-9`、`a-f` 和 `A-F`，大小写混用表示
37	    /// 同一个 32 字节值；解析结果可与 [`digest_reader`] 的结果直接比较，
38	    /// 再经 [`to_hex`](Self::to_hex) 显示时始终是完整的 64 个小写十六进制
39	    /// 字符，前导零不会丢失。
40	    ///
41	    /// 入参按原始字节处理，不要求是合法 UTF-8（例如操作系统给出的命令行
42	    /// 参数可能无法解码）：长度先按字节数判断，必须恰好为 64；长度正确时
43	    /// 报告首个非法字节从零开始的字节偏移。不做任何裁剪或修正，空白、末尾
44	    /// 换行、`0x` 前缀以及非 ASCII 字节都属于格式错误。
45	    pub fn from_hex_bytes(bytes: &[u8]) -> Result<Sha256Digest, ParseDigestError> {
46	        if bytes.len() != 64 {
47	            return Err(ParseDigestError::InvalidLength(bytes.len()));
48	        }
49	        let mut out = [0u8; 32];
50	        for (i, pair) in bytes.chunks_exact(2).enumerate() {
51	            let hi = hex_nibble(pair[0])
52	                .ok_or(ParseDigestError::InvalidHexChar(2 * i))?;
53	            let lo = hex_nibble(pair[1])
54	                .ok_or(ParseDigestError::InvalidHexChar(2 * i + 1))?;
55	            out[i] = (hi << 4) | lo;
56	        }
57	        Ok(Sha256Digest(out))
58	    }
59	}
