73	/// 从十六进制文本解析 [`Sha256Digest`] 失败时返回的类型化错误。
74	///
75	/// 两类失败可以按变体区分：长度不符时携带输入的实际 UTF-8 字节长度；
76	/// 长度正确但含非法字符时携带首个非法字节从零开始的字节偏移。
77	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
78	pub enum ParseDigestError {
79	    /// 输入的 UTF-8 字节长度不是 64；携带实际字节长度。
80	    InvalidLength(usize),
81	    /// 长度为 64 但含有非十六进制字符；携带首个非法字节的字节偏移
82	    /// （按原始文本的字节计算，不按字符个数）。
83	    InvalidHexChar(usize),
84	}
85	
86	impl ParseDigestError {
87	    /// 长度不符时返回输入的实际字节长度，否则返回 `None`。
88	    pub fn actual_length(&self) -> Option<usize> {
89	        match self {
90	            ParseDigestError::InvalidLength(len) => Some(*len),
91	            ParseDigestError::InvalidHexChar(_) => None,
92	        }
93	    }
94	
95	    /// 含非法字符时返回首个非法字节的字节偏移，否则返回 `None`。
96	    pub fn invalid_position(&self) -> Option<usize> {
97	        match self {
98	            ParseDigestError::InvalidLength(_) => None,
99	            ParseDigestError::InvalidHexChar(pos) => Some(*pos),
100	        }
101	    }
102	}
103	
104	impl fmt::Display for ParseDigestError {
105	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
106	        match self {
107	            ParseDigestError::InvalidLength(len) => write!(
108	                f,
109	                "digest must be exactly 64 ASCII hexadecimal characters, got {len} bytes"
110	            ),
111	            ParseDigestError::InvalidHexChar(pos) => {
112	                write!(f, "digest contains a non-hexadecimal byte at offset {pos}")
113	            }
114	        }
115	    }
116	}
117	
118	impl Error for ParseDigestError {}
119	
120	fn hex_nibble(b: u8) -> Option<u8> {
121	    match b {
122	        b'0'..=b'9' => Some(b - b'0'),
123	        b'a'..=b'f' => Some(b - b'a' + 10),
124	        b'A'..=b'F' => Some(b - b'A' + 10),
125	        _ => None,
126	    }
127	}
128	
129	impl std::str::FromStr for Sha256Digest {
130	    type Err = ParseDigestError;
131	
132	    /// 从 64 个 ASCII 十六进制字符解析摘要。
133	    ///
134	    /// 接受 `0-9`、`a-f` 和 `A-F`，大小写混用表示同一个摘要。输入必须
135	    /// 恰好是 64 个字符：不做任何裁剪或修正，空白、末尾换行、`0x` 前缀、
136	    /// 分隔符以及全角数字等非 ASCII 内容都属于格式错误。长度按输入的
137	    /// UTF-8 字节数判断，非法字符的位置也按字节偏移报告。
138	    fn from_str(s: &str) -> Result<Self, Self::Err> {
139	        Sha256Digest::from_hex_bytes(s.as_bytes())
140	    }
141	}
142	
143	/// 计算摘要过程中读取输入失败时返回的类型化错误。
144	#[derive(Debug)]
145	pub struct DigestError(io::Error);
146	
147	impl DigestError {
148	    /// 取出底层的 I/O 错误。
149	    pub fn into_inner(self) -> io::Error {
150	        self.0
151	    }
152	}
153	
154	impl fmt::Display for DigestError {
155	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
156	        write!(f, "failed to read input: {}", self.0)
157	    }
158	}
159	
160	impl Error for DigestError {
161	    fn source(&self) -> Option<&(dyn Error + 'static)> {
162	        Some(&self.0)
163	    }
164	}
165	
166	impl From<io::Error> for DigestError {
167	    fn from(err: io::Error) -> Self {
168	        DigestError(err)
169	    }
170	}
171	
172	/// 以流式方式读取 `reader` 的全部字节并计算 SHA-256 摘要。
173	///
174	/// 内存占用与输入大小无关。读取失败时返回 [`DigestError`]，绝不返回部分内容的摘要。
175	///
176	/// [`io::ErrorKind::Interrupted`] 是临时中断而非输入结束：本次读取没有
177	/// 消费任何字节，直接重试同一位置，摘要与未发生中断时完全一致。其他
178	/// 错误（权限不足、数据损坏等）仍然立即失败。
179	pub fn digest_reader<R: Read>(mut reader: R) -> Result<Sha256Digest, DigestError> {
180	    let mut hasher = Sha256::new();
181	    let mut buf = [0u8; 64 * 1024];
182	    loop {
183	        match reader.read(&mut buf) {
184	            Ok(0) => break,
185	            Ok(n) => hasher.update(&buf[..n]),
186	            Err(ref err) if err.kind() == io::ErrorKind::Interrupted => continue,
187	            Err(err) => return Err(DigestError(err)),
188	        }
189	    }
190	    Ok(Sha256Digest(hasher.finalize().into()))
191	}
