193	/// Ed25519 公钥，由 DER 编码的 SubjectPublicKeyInfo 导入。
194	///
195	/// 与 [`Sha256Digest`] 是两个明确区分的类型：公钥不是摘要，不能把公钥
196	/// 当作摘要解析，也不能用摘要的十六进制解析入口还原公钥。文本表示固定
197	/// 为 64 个小写十六进制字符（保留前导零，不含标签或换行），表示公钥
198	/// 本身的 32 字节，**不是**公钥的 SHA-256 摘要。
199	#[derive(Clone, Copy, PartialEq, Eq, Hash)]
200	pub struct Ed25519PublicKey([u8; 32]);
201	
202	impl Ed25519PublicKey {
203	    /// 从 DER 编码的 SubjectPublicKeyInfo（RFC 8410）原始字节导入公钥。
204	    ///
205	    /// 入参是**二进制**的公钥容器：恰好一份完整、规范的 DER 对象。
206	    /// 裸公钥、十六进制文本和 PEM 文本都不属于本入口接受的格式，不做
207	    /// 任何格式猜测或文本转换。
208	    ///
209	    /// 接受范围遵循 RFC 8410 对 Ed25519 公钥的规定：算法标识为
210	    /// `1.3.101.112`，算法参数必须缺省（即使写成 NULL 也拒绝），公钥
211	    /// 所在位串的未使用位数为零，公钥内容恰好 32 字节。截断数据、声明
212	    /// 长度与实际内容不符、非规范长度编码、容器中出现多余字段或对象
213	    /// 之后还有字节都返回 [`ImportPublicKeyError::Malformed`]，不忽略
214	    /// 剩余内容，也不自动补齐。整体编码合法但算法标识不是 Ed25519 时
215	    /// 返回 [`ImportPublicKeyError::UnsupportedAlgorithm`]，并保留实际
216	    /// 标识供调用方展示。
217	    ///
218	    /// 导入成功只表示编码被接受：不表示已验证任何文件签名，也不表示
219	    /// 确认了公钥持有者的身份。
220	    pub fn from_spki_der(der: &[u8]) -> Result<Ed25519PublicKey, ImportPublicKeyError> {
221	        const MALFORMED: ImportPublicKeyError = ImportPublicKeyError::Malformed;
222	
223	        // 外层：恰好一个 SEQUENCE，对象之后不允许有任何字节。
224	        let (tag, spki, rest) = read_der_tlv(der).ok_or(MALFORMED)?;
225	        if tag != TAG_SEQUENCE || !rest.is_empty() {
226	            return Err(MALFORMED);
227	        }
228	        // SubjectPublicKeyInfo 内部：恰好 algorithm 与 subjectPublicKey 两项。
229	        let (tag, algorithm, rest) = read_der_tlv(spki).ok_or(MALFORMED)?;
230	        if tag != TAG_SEQUENCE {
231	            return Err(MALFORMED);
232	        }
233	        let (tag, bit_string, rest) = read_der_tlv(rest).ok_or(MALFORMED)?;
234	        if tag != TAG_BIT_STRING || !rest.is_empty() {
235	            return Err(MALFORMED);
236	        }
237	        // AlgorithmIdentifier 内部：恰好一个 OID，没有任何参数——
238	        // RFC 8410 要求参数缺省，写成 NULL 同样拒绝。
239	        let (tag, oid_content, rest) = read_der_tlv(algorithm).ok_or(MALFORMED)?;
240	        if tag != TAG_OID || !rest.is_empty() {
241	            return Err(MALFORMED);
242	        }
243	        let algorithm_oid = decode_oid(oid_content).ok_or(MALFORMED)?;
244	        // 位串：未使用位数为零，公钥内容恰好 32 字节。
245	        let (&unused_bits, key) = bit_string.split_first().ok_or(MALFORMED)?;
246	        if unused_bits != 0 || key.len() != 32 {
247	            return Err(MALFORMED);
248	        }
249	
250	        // 只有整体结构完整、DER 合法时才判断算法：编码已损坏的输入
251	        // 一律报格式错误，不因局部看到其他算法标识而改报算法不支持。
252	        if algorithm_oid.arcs() != [1, 3, 101, 112] {
253	            return Err(ImportPublicKeyError::UnsupportedAlgorithm(algorithm_oid));
254	        }
255	
256	        let mut bytes = [0u8; 32];
257	        bytes.copy_from_slice(key);
258	        Ok(Ed25519PublicKey(bytes))
259	    }
260	
261	    /// 返回公钥的原始 32 字节。
262	    pub fn as_bytes(&self) -> &[u8; 32] {
263	        &self.0
264	    }
265	
266	    /// 返回 64 个小写十六进制字符（保留前导零，不含标签或换行）。
267	    ///
268	    /// 这是公钥本身的文本表示，不是公钥的 SHA-256 摘要。
269	    pub fn to_hex(&self) -> String {
270	        let mut hex = String::with_capacity(64);
271	        for byte in self.0 {
272	            hex.push(char::from_digit((byte >> 4) as u32, 16).unwrap());
273	            hex.push(char::from_digit((byte & 0x0f) as u32, 16).unwrap());
274	        }
275	        hex
276	    }
277	}
