291	/// 对象标识符（OID），以各段弧的数值保存，用于向调用方展示实际标识。
292	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
293	pub struct ObjectIdentifier(Vec<u64>);
294	
295	impl ObjectIdentifier {
296	    /// 返回各段弧的数值，例如 Ed25519 为 `[1, 3, 101, 112]`。
