496	    /// 用于模拟不同分块方式，验证摘要只取决于字节内容而非读取方式。
497	    struct ChunkedReader<'a> {
498	        data: &'a [u8],
499	        pos: usize,
500	        chunk_sizes: &'a [usize],
501	        chunk_index: usize,
502	    }
