/// 与 [`spki_der`] 相同的 SPKI 结构，但不假设各部分长度都能用短形式
/// 单字节表示：算法 OID 内容或位串长度变大（例如某个弧按 base-128
/// 占多个编码字节）时，算法序列与外层序列的长度改用 DER 长形式。
/// 其余结构约定不变：算法参数缺省，位串未使用位数为零。
fn spki_der_with(oid_content: &[u8], key: &[u8]) -> Vec<u8> {
    let mut algorithm = vec![0x06];
    algorithm.extend_from_slice(&der_len(oid_content.len()));
    algorithm.extend_from_slice(oid_content);

    let mut bit_string = vec![0x03];
    // 位串内容 = 1 字节未使用位数 + 公钥。
    bit_string.extend_from_slice(&der_len(1 + key.len()));
    bit_string.push(0x00);
    bit_string.extend_from_slice(key);

    let mut spki_content = Vec::new();
    spki_der_with_push_tlv(&mut spki_content, 0x30, &algorithm);
    spki_der_with_push_tlv(&mut spki_content, 0x03, &bit_string[2..]);

    let mut der = Vec::new();
    spki_der_with_push_tlv(&mut der, 0x30, &spki_content);
    der
}

/// 规范的 DER 定长编码：短于 128 用短形式，否则用最短的长形式。
fn der_len(len: usize) -> Vec<u8> {
    if len < 0x80 {
        vec![len as u8]
    } else {
        let mut bytes = Vec::new();
        let mut rest = len;
        while rest > 0 {
            bytes.push((rest & 0xff) as u8);
            rest >>= 8;
        }
        bytes.reverse();
        let mut out = vec![0x80 | bytes.len() as u8];
        out.extend_from_slice(&bytes);
        out
    }
}

/// 追加一个通用单字节标签的 TLV。
fn spki_der_with_push_tlv(out: &mut Vec<u8>, tag: u8, content: &[u8]) {
    out.push(tag);
    out.extend_from_slice(&der_len(content.len()));
    out.extend_from_slice(content);
}

